// ABR-related things
//---------------
const abrProps: Hang.ConnectionProps = { url: new URL("https://domain.name.here:4443/anon/abr") };
const abrConnection = new Hang.Connection(abrProps);
const abrBroadcastName = "abr" as Moq.Path.Valid;
const abrPublish = new Hang.Publish.Broadcast(abrConnection, {enabled: true, name: abrBroadcastName, controller: { enabled: true, message: "" }});

const increaseBitrate = () => {
	console.log("Setting bitrate: high");
	abrPublish.controller?.message.set('high');
	console.log("Sent request to backend");
}

const lowerBitrate = () => {
	console.log("Setting bitrate: low");
	abrPublish.controller?.message.set('low');
	console.log("Sent request to backend");
}

const normalizeBitrate = () => {
	console.log("Setting bitrate: normalized");
	abrPublish.controller?.message.set(`abr;8000`);
	console.log("Sent request to backend");
}

document.addEventListener("keydown", (event) => {
	const keyName = event.key;

	//console.log(`${keyName}`);

	if (keyName ==='l') { // Lower the bitrate
		lowerBitrate();
	} else if (keyName === 'h') { // Increase the bitrate
		increaseBitrate();
	} else if (keyName === 't') { // Test bandwidth estimation
		getBandwidthEstimation();
	} else if (keyName === 'k') {
		runSpreedrates(speedrates);
	} else if (keyName === 'n') {
		normalizeBitrate();
	}
})

const getBandwidthEstimation = async() => {
	const startingTime = Date.now();
	// Run the fetching here
	const url = "https://domain.name.here:5173/bin"; // URL for the binary file used for measurement
	try {
		const response = await fetch(url);
		//console.log(response);
		const endingTime = Date.now();
		const delay = endingTime - startingTime - 50; // milliseconds, removing some overhead
		//console.log(`endingtime: ${delay}`);

		let newBitrate = Math.round(1000/(delay/1000)); // 1 MB / (delay in seconds)
		if (newBitrate < 1 || newBitrate > 8000) {
			newBitrate = 8000;
		}
		console.log(newBitrate);

		// Send a message to backend to set the bitrate properly
		// Format is "abr;<bitrate>", i.e. "abr;3818" to show that this is really something coordinated to the ABR controller
		abrPublish.controller?.message.set(`abr;${newBitrate}`);
		// ToDo! Edit the backend to be able to set the bitrate as supposed to
		// i.e. match the form (including "abr;")
		console.log("Bitrate request sent to the client");


	} catch (error) {
		console.error("Error found while downloading the binary/setting the bitrate! ", error);
	}
	//
	//const endingTime = Date.now();
}

